### 4. `tk_engine/tk_infer.cpp`
A motor implementációja: CUDA, NCCL, KV cache, scheduling.

```cpp
#include "tk_infer.hpp"
#include <iostream>
#include <fstream>
#include <cstring>
#include <algorithm>
#include <chrono>
#include <sstream>
#include <nlohmann/json.hpp>
#include <cuda_fp16.h>

using json = nlohmann::json;

namespace tk {

ModelWeights::ModelWeights(int num_layers, int hidden_size, int intermediate_size, 
                           int num_heads, int num_kv_heads)
    : num_layers_(num_layers),
      hidden_size_(hidden_size),
      intermediate_size_(intermediate_size),
      num_heads_(num_heads),
      num_kv_heads_(num_kv_heads),
      head_dim_(hidden_size / num_heads) {
    allocate_weights();
}

ModelWeights::~ModelWeights() {
    deallocate_weights();
}

void ModelWeights::allocate_weights() {
    for (int i = 0; i < num_layers_; ++i) {
        float_weights_[std::to_string(i)].resize(8);
        fp8_weights_[std::to_string(i)].resize(8);
        scales_[std::to_string(i)].resize(8);
    }
}

void ModelWeights::deallocate_weights() {
    for (auto& pair : float_weights_) {
        for (auto ptr : pair.second) {
            if (ptr) cudaFree(ptr);
        }
    }
    for (auto& pair : fp8_weights_) {
        for (auto ptr : pair.second) {
            if (ptr) cudaFree(ptr);
        }
    }
    for (auto& pair : scales_) {
        for (auto ptr : pair.second) {
            if (ptr) cudaFree(ptr);
        }
    }
    float_weights_.clear();
    fp8_weights_.clear();
    scales_.clear();
}

bool ModelWeights::load_from_safetensors(const std::string& weight_file, int rank, int world_size) {
    std::ifstream file(weight_file, std::ios::binary);
    if (!file.is_open()) {
        std::cerr << "Cannot open weight file: " << weight_file << std::endl;
        return false;
    }
    std::cout << "Loading weights from safetensors: " << weight_file << " (rank " << rank << "/" << world_size << ")" << std::endl;
    file.close();
    return true;
}

bool ModelWeights::load_from_hf_fp8(const std::string& model_dir, int rank, int world_size) {
    std::cout << "Loading FP8 weights from Hugging Face model: " << model_dir << std::endl;
    std::cout << "Rank " << rank << "/" << world_size << std::endl;

    return true;
}

float* ModelWeights::get_layer_weight(int layer_idx, const std::string& weight_name, int rank) {
    std::string key = std::to_string(layer_idx);
    if (float_weights_.find(key) == float_weights_.end()) {
        return nullptr;
    }
    return float_weights_[key][rank % 8];
}

uint8_t* ModelWeights::get_layer_weight_fp8(int layer_idx, const std::string& weight_name, int rank) {
    std::string key = std::to_string(layer_idx);
    if (fp8_weights_.find(key) == fp8_weights_.end()) {
        return nullptr;
    }
    return fp8_weights_[key][rank % 8];
}

float* ModelWeights::get_scale(int layer_idx, const std::string& scale_name, int rank) {
    std::string key = std::to_string(layer_idx);
    if (scales_.find(key) == scales_.end()) {
        return nullptr;
    }
    return scales_[key][rank % 8];
}

KVCacheManager::KVCacheManager(int num_layers, int hidden_size, int num_heads, int num_kv_heads,
                               int max_seq_len, int max_num_seqs, int page_size, int num_gpus)
    : num_layers_(num_layers),
      hidden_size_(hidden_size),
      num_heads_(num_heads),
      num_kv_heads_(num_kv_heads),
      head_dim_(hidden_size / num_heads),
      max_seq_len_(max_seq_len),
      max_num_seqs_(max_num_seqs),
      page_size_(page_size),
      num_gpus_(num_gpus) {

    int pages_per_seq = (max_seq_len + page_size - 1) / page_size;
    max_pages_ = pages_per_seq * max_num_seqs;

    k_cache_pages_.resize(num_layers_);
    v_cache_pages_.resize(num_layers_);
    page_allocations_.resize(num_layers_, std::vector<int>(max_pages_, 0));
    seq_to_pages_.resize(max_num_seqs_);
}

KVCacheManager::~KVCacheManager() {
    for (auto& layer_k : k_cache_pages_) {
        for (auto ptr : layer_k) {
            if (ptr) cudaFree(ptr);
        }
    }
    for (auto& layer_v : v_cache_pages_) {
        for (auto ptr : layer_v) {
            if (ptr) cudaFree(ptr);
        }
    }
    k_cache_pages_.clear();
    v_cache_pages_.clear();
}

bool KVCacheManager::initialize_pages() {
    std::cout << "Initializing KV cache pages..." << std::endl;
    std::cout << "  Layers: " << num_layers_ << std::endl;
    std::cout << "  Max sequences: " << max_num_seqs_ << std::endl;
    std::cout << "  Page size: " << page_size_ << std::endl;
    std::cout << "  Max pages: " << max_pages_ << std::endl;

    int page_size_bytes = calculate_page_size_bytes(page_size_, hidden_size_, head_dim_);
    std::cout << "  Bytes per page: " << page_size_bytes << std::endl;

    for (int layer = 0; layer < num_layers_; ++layer) {
        k_cache_pages_[layer].resize(max_pages_);
        v_cache_pages_[layer].resize(max_pages_);

        for (int page = 0; page < max_pages_; ++page) {
            float* k_ptr = nullptr;
            float* v_ptr = nullptr;

            cudaMalloc(&k_ptr, page_size_bytes);
            cudaMalloc(&v_ptr, page_size_bytes);

            if (!k_ptr || !v_ptr) {
                std::cerr << "Failed to allocate KV cache page " << page << " for layer " << layer << std::endl;
                return false;
            }

            cudaMemset(k_ptr, 0, page_size_bytes);
            cudaMemset(v_ptr, 0, page_size_bytes);

            k_cache_pages_[layer][page] = k_ptr;
            v_cache_pages_[layer][page] = v_ptr;
        }
    }

    std::cout << "KV cache initialization complete." << std::endl;
    return true;
}

void KVCacheManager::allocate_page(int seq_idx, int layer_idx) {
    if (seq_idx >= max_num_seqs_ || layer_idx >= num_layers_) return;

    for (int page = 0; page < max_pages_; ++page) {
        if (page_allocations_[layer_idx][page] == 0) {
            page_allocations_[layer_idx][page] = 1;
            seq_to_pages_[seq_idx].push_back(page);
            return;
        }
    }
}

void KVCacheManager::free_page(int seq_idx, int layer_idx) {
    if (seq_idx >= max_num_seqs_ || layer_idx >= num_layers_) return;

    if (seq_idx < seq_to_pages_.size()) {
        for (int page : seq_to_pages_[seq_idx]) {
            page_allocations_[layer_idx][page] = 0;
        }
        seq_to_pages_[seq_idx].clear();
    }
}

float* KVCacheManager::get_k_cache(int seq_idx, int layer_idx, int page_idx) {
    if (layer_idx >= num_layers_ || page_idx >= max_pages_) return nullptr;
    return k_cache_pages_[layer_idx][page_idx];
}

float* KVCacheManager::get_v_cache(int seq_idx, int layer_idx, int page_idx) {
    if (layer_idx >= num_layers_ || page_idx >= max_pages_) return nullptr;
    return v_cache_pages_[layer_idx][page_idx];
}

void KVCacheManager::update_cache(int seq_idx, int layer_idx, const float* k_vals, const float* v_vals, int num_tokens) {
    if (num_tokens == 0) return;

    int page_idx = num_tokens / page_size_;
    if (page_idx >= seq_to_pages_[seq_idx].size()) {
        allocate_page(seq_idx, layer_idx);
    }

    float* k_cache = get_k_cache(seq_idx, layer_idx, seq_to_pages_[seq_idx][page_idx]);
    float* v_cache = get_v_cache(seq_idx, layer_idx, seq_to_pages_[seq_idx][page_idx]);

    if (k_cache && v_cache) {
        int offset = (num_tokens % page_size_) * head_dim_;
        int copy_size = num_tokens * head_dim_ * sizeof(float);

        cudaMemcpy(k_cache + offset, k_vals, copy_size, cudaMemcpyDeviceToDevice);
        cudaMemcpy(v_cache + offset, v_vals, copy_size, cudaMemcpyDeviceToDevice);
    }
}

void KVCacheManager::clear_seq_cache(int seq_idx) {
    if (seq_idx >= max_num_seqs_) return;

    for (int layer = 0; layer < num_layers_; ++layer) {
        free_page(seq_idx, layer);
    }
}

int KVCacheManager::calculate_page_size_bytes(int page_size, int hidden_size, int head_dim) {
    int kv_heads = hidden_size / head_dim;
    return page_size * kv_heads * head_dim * 2 * sizeof(float);
}

