void TokenScheduler::update_session(const InferenceSession& session) {
    if (active_sessions_.find(session.session_id) != active_sessions_.end()) {
        active_sessions_[session.session_id] = session;
    }
}

std::vector<InferenceSession> TokenScheduler::get_batch() {
    std::vector<InferenceSession> batch;
    int total_tokens = 0;

    std::vector<std::string> to_remove;

    while (!ready_queue_.empty() && batch.size() < max_num_seqs_) {
        std::string session_id = ready_queue_.front();
        ready_queue_.pop();

        if (active_sessions_.find(session_id) == active_sessions_.end()) {
            continue;
        }

        InferenceSession& session = active_sessions_[session_id];

        if (!session.is_active) {
            to_remove.push_back(session_id);
            continue;
        }

        int tokens = session.input_ids.size() + session.output_ids.size();

        if (total_tokens + tokens <= max_num_batched_tokens_) {
            batch.push_back(session);
            total_tokens += tokens;

            if (session.num_generated < session.max_new_tokens) {
                ready_queue_.push(session_id);
            } else {
                session.is_active = false;
                to_remove.push_back(session_id);
            }
        } else {
            ready_queue_.push(session_id);
            break;
        }
    }

    for (const auto& session_id : to_remove) {
        active_sessions_.erase(session_id);
    }

    return batch;
}

InferenceSession TokenScheduler::get_session(const std::string& session_id) {
    if (active_sessions_.find(session_id) != active_sessions_.end()) {
        return active_sessions_[session_id];
    }
    return InferenceSession{};
}

bool TokenScheduler::has_active_sessions() const {
    return !active_sessions_.empty();
}

