bool TKEngine::initialize() {
    std::cout << "Initializing TKEngine..." << std::endl;

    if (!initialize_cuda()) {
        std::cerr << "CUDA initialization failed" << std::endl;
        return false;
    }

    if (!initialize_nccl()) {
        std::cerr << "NCCL initialization failed" << std::endl;
        return false;
    }

    if (!load_model_config()) {
        std::cerr << "Failed to load model config" << std::endl;
        return false;
    }

    if (!load_quant_config()) {
        std::cerr << "Failed to load quant config" << std::endl;
        return false;
    }

    weights_ = std::make_shared<ModelWeights>(
        model_config_.num_hidden_layers,
        model_config_.hidden_size,
        model_config_.intermediate_size,
        model_config_.num_attention_heads,
        model_config_.num_key_value_heads
    );

    kv_cache_ = std::make_shared<KVCacheManager>(
        model_config_.num_hidden_layers,
        model_config_.hidden_size,
        model_config_.num_attention_heads,
        model_config_.num_key_value_heads,
        max_model_len_,
        max_num_seqs_,
        128,
        tensor_parallel_size_
    );

    if (!kv_cache_->initialize_pages()) {
        std::cerr << "KV cache initialization failed" << std::endl;
        return false;
    }

    scheduler_ = std::make_shared<TokenScheduler>(max_num_seqs_, max_num_batched_tokens_, 512);

    std::cout << "TKEngine initialized successfully" << std::endl;
    return true;
}

bool TKEngine::initialize_cuda() {
    std::cout << "Initializing CUDA..." << std::endl;

    int device_count = 0;
    cudaGetDeviceCount(&device_count);
    std::cout << "Found " << device_count << " CUDA devices" << std::endl;

    if (device_count < tensor_parallel_size_) {
        std::cerr << "Not enough CUDA devices for TP=" << tensor_parallel_size_ << std::endl;
        return false;
    }

    gpu_rank_ = 0;
    cudaSetDevice(gpu_rank_);

    cudaStreamCreate(&compute_stream_);
    cudaStreamCreate(&h2d_stream_);
    cudaStreamCreate(&d2h_stream_);

    std::cout << "CUDA initialized on device " << gpu_rank_ << std::endl;
    return true;
}

bool TKEngine::initialize_nccl() {
    std::cout << "Initializing NCCL..." << std::endl;

    ncclUniqueId nccl_id;
    ncclGetUniqueId(&nccl_id);

    ncclCommInitRank(&nccl_comm_, tensor_parallel_size_, nccl_id, gpu_rank_);

    std::cout << "NCCL initialized for rank " << gpu_rank_ << "/" << tensor_parallel_size_ << std::endl;
    return true;
}

bool TKEngine::load_model_config() {
    std::string config_path = model_dir_ + "/config.json";
    return load_json_config(config_path, model_config_);
}

bool TKEngine::load_quant_config() {
    std::string quant_path = model_dir_ + "/quantization_config.json";

    std::ifstream file(quant_path);
    if (!file.is_open()) {
        std::cout << "Quantization config not found, using defaults" << std::endl;
        return true;
    }

    try {
        json config;
        file >> config;

        quant_config_.quant_method = config.value("quant_method", "fp8");
        quant_config_.group_wise = config.value("group_wise", true);
        quant_config_.group_size = config.value("group_size", 128);

        std::cout << "Loaded quantization config: " << quant_config_.quant_method << std::endl;
        return true;
    } catch (const std::exception& e) {
        std::cerr << "Error parsing quantization config: " << e.what() << std::endl;
        return false;
    }
}

bool TKEngine::load_model() {
    std::cout << "Loading model from " << model_dir_ << std::endl;

    if (!weights_) {
        std::cerr << "Weights not initialized" << std::endl;
        return false;
    }

    bool success = false;

    if (quant_config_.quant_method == "fp8") {
        success = weights_->load_from_hf_fp8(model_dir_, gpu_rank_, tensor_parallel_size_);
    } else {
        std::string weight_file = model_dir_ + "/model.safetensors";
        success = weights_->load_from_safetensors(weight_file, gpu_rank_, tensor_parallel_size_);
    }

    if (!success) {
        std::cerr << "Failed to load model weights" << std::endl;
        return false;
    }

    std::cout << "Model loaded successfully" << std::endl;
    return true;
}

void TKEngine::shutdown() {
    std::cout << "Shutting down TKEngine..." << std::endl;

    if (compute_stream_) cudaStreamDestroy(compute_stream_);
    if (h2d_stream_) cudaStreamDestroy(h2d_stream_);
    if (d2h_stream_) cudaStreamDestroy(d2h_stream_);

    if (nccl_comm_) ncclCommDestroy(nccl_comm_);

    weights_.reset();
    kv_cache_.reset();
    scheduler_.reset();

    std::cout << "TKEngine shut down" << std::endl;
}

bool TKEngine::run_inference(const ChatCompletionRequest& req, ChatCompletionResponse& res) {
    std::cout << "Running inference for model: " << req.model << std::endl;

    std::string session_id = create_session(req);
    std::cout << "Created session: " << session_id << std::endl;

    InferenceSession session = scheduler_->get_session(session_id);

    while (session.is_active && session.num_generated < session.max_new_tokens) {
        std::vector<InferenceSession> batch = scheduler_->get_batch();

        if (batch.empty()) {
            std::cerr << "No active sessions in batch" << std::endl;
            break;
        }

        if (!inference_step_batch(batch)) {
            std::cerr << "Inference step failed" << std::endl;
            break;
        }

        session = scheduler_->get_session(session_id);

        if (session.num_generated >= session.max_new_tokens) {
            session.is_active = false;
            scheduler_->update_session(session);
        }
    }

    std::vector<int> output_ids = get_session_output(session_id);

    res.id = "glm-" + session_id;
    res.created = std::chrono::system_clock::now().time_since_epoch().count() / 1000000000LL;
    res.model = "glm-4.7-fp8";

    Choice choice;
    choice.message.role = "assistant";
    choice.message.content = "Generated response";
    choice.finish_reason = session.num_generated >= session.max_new_tokens ? "length" : "stop";
    choice.index = 0;

    res.choices.push_back(choice);
    res.usage.prompt_tokens = session.input_ids.size();
    res.usage.completion_tokens = session.output_ids.size();
    res.usage.total_tokens = res.usage.prompt_tokens + res.usage.completion_tokens;

    destroy_session(session_id);

    return true;
}

bool TKEngine::inference_step_batch(std::vector<InferenceSession>& batch) {
    std::cout << "Running inference step for batch of " << batch.size() << " sessions" << std::endl;

    for (auto& session : batch) {
        session.num_generated += 1;

        int new_token = 0;
        session.output_ids.push_back(new_token);
    }

    return true;
}

std::string TKEngine::create_session(const ChatCompletionRequest& req) {
    static int session_counter = 0;
    std::string session_id = "sess_" + std::to_string(session_counter++);

    InferenceSession session;
    session.session_id = session_id;
    session.max_new_tokens = req.max_tokens;
    session.temperature = req.temperature;
    session.top_p = req.top_p;
    session.top_k = req.top_k;
    session.is_active = true;
    session.created_at = std::chrono::system_clock::now().time_since_epoch().count() / 1000000000LL;

    session.input_ids.push_back(1);

    scheduler_->add_session(session);

    return session_id;
}

void TKEngine::destroy_session(const std::string& session_id) {
    scheduler_->remove_session(session_id);

    if (kv_cache_) {
        for (int seq_idx = 0; seq_idx < max_num_seqs_; ++seq_idx) {
            kv_cache_->clear_seq_cache(seq_idx);
        }
    }
}

std::vector<int> TKEngine::get_session_output(const std::string& session_id) {
    InferenceSession session = scheduler_->get_session(session_id);
    return session.output_ids;
}

