class TKServer {
public:
    TKServer(const ServerConfig& config) : config_(config), engine_(nullptr) {}

    bool initialize() {
        std::cout << "Initializing TKServer..." << std::endl;
        std::cout << "  Host: " << config_.host << std::endl;
        std::cout << "  Port: " << config_.port << std::endl;
        std::cout << "  Model Dir: " << config_.model_dir << std::endl;
        std::cout << "  TP Size: " << config_.tensor_parallel_size << std::endl;

        engine_ = std::make_unique<tk::TKEngine>(
            config_.model_dir,
            config_.tensor_parallel_size,
            config_.gpu_memory_fraction,
            config_.max_model_len,
            config_.max_num_seqs,
            config_.max_num_batched_tokens
        );

        if (!engine_->initialize()) {
            std::cerr << "Failed to initialize TKEngine" << std::endl;
            return false;
        }

        if (!engine_->load_model()) {
            std::cerr << "Failed to load model" << std::endl;
            return false;
        }

        std::cout << "TKServer initialized successfully" << std::endl;
        return true;
    }

    void shutdown() {
        std::cout << "Shutting down TKServer..." << std::endl;
        if (engine_) {
            engine_->shutdown();
            engine_.reset();
        }
    }

    bool start() {
        auto router = std::make_unique<router_t>();

        router->http_get("/health", 
            [this](auto req, auto) {
                return req->create_response(restinio::status_ok())
                    .set_body("OK")
                    .done();
            });

        router->http_post("/v1/chat/completions",
            [this](auto req, auto) {
                return this->handle_chat_completion(req);
            });

        router->http_post("/v1/completions",
            [this](auto req, auto) {
                return this->handle_completion(req);
            });

        router->http_get("/v1/models",
            [this](auto req, auto) {
                return this->handle_list_models(req);
            });

        restinio::run(
            restinio::on_this_thread<traits_t>(config_.port)
                .port(config_.port)
                .bind(config_.host)
                .request_handler(std::move(router)));

        return true;
    }

private:
    ServerConfig config_;
    std::unique_ptr<tk::TKEngine> engine_;

    auto handle_chat_completion(auto req) {
        std::cout << "Handling /v1/chat/completions request" << std::endl;

        try {
            std::string body = req->body();
            json request_json = json::parse(body);

            tk::ChatCompletionRequest req_obj;
            req_obj.model = request_json.value("model", "glm-4.7-fp8");
            req_obj.temperature = request_json.value("temperature", 0.7f);
            req_obj.top_p = request_json.value("top_p", 0.9f);
            req_obj.top_k = request_json.value("top_k", 50);
            req_obj.max_tokens = request_json.value("max_tokens", 512);
            req_obj.stream = request_json.value("stream", false);

            if (request_json.contains("messages") && request_json["messages"].is_array()) {
                for (const auto& msg : request_json["messages"]) {
                    tk::ChatMessage cm;
                    cm.role = msg.value("role", "");
                    cm.content = msg.value("content", "");
