            std::cerr << "Error: " << e.what() << std::endl;
            json error_json = {
                {"error", {
                    {"message", std::string("Server error: ") + e.what()},
                    {"type", "server_error"},
                    {"param", nullptr},
                    {"code", "server_error"}
                }}
            };
            return req->create_response(restinio::status_internal_server_error())
                .set_body(error_json.dump())
                .append_header("Content-Type", "application/json")
                .done();
        }
    }

    auto handle_completion(auto req) {
        std::cout << "Handling /v1/completions request" << std::endl;

        try {
            std::string body = req->body();
            json request_json = json::parse(body);

            tk::ChatCompletionRequest req_obj;
            req_obj.model = request_json.value("model", "glm-4.7-fp8");
            req_obj.temperature = request_json.value("temperature", 0.7f);
            req_obj.top_p = request_json.value("top_p", 0.9f);
            req_obj.top_k = request_json.value("top_k", 50);
            req_obj.max_tokens = request_json.value("max_tokens", 512);

            if (request_json.contains("prompt")) {
                std::string prompt = request_json["prompt"];
                tk::ChatMessage msg;
                msg.role = "user";
                msg.content = prompt;
                req_obj.messages.push_back(msg);
            }

            tk::ChatCompletionResponse res;

            if (!engine_->run_inference(req_obj, res)) {
                json error_json = {
                    {"error", {
                        {"message", "Inference failed"},
                        {"type", "inference_error"}
                    }}
                };
                return req->create_response(restinio::status_internal_server_error())
                    .set_body(error_json.dump())
                    .append_header("Content-Type", "application/json")
                    .done();
            }

            json response_json = {
                {"id", res.id},
                {"object", "text_completion"},
                {"created", res.created},
                {"model", res.model},
                {"choices", json::array()},
                {"usage", {
                    {"prompt_tokens", res.usage.prompt_tokens},
                    {"completion_tokens", res.usage.completion_tokens},
                    {"total_tokens", res.usage.total_tokens}
                }}
            };

            for (const auto& choice : res.choices) {
                json choice_json = {
                    {"index", choice.index},
                    {"text", choice.message.content},
                    {"finish_reason", choice.finish_reason}
                };
                response_json["choices"].push_back(choice_json);
            }

            return req->create_response(restinio::status_ok())
                .set_body(response_json.dump())
                .append_header("Content-Type", "application/json")
                .done();
        } catch (const std::exception& e) {
            std::cerr << "Error: " << e.what() << std::endl;
            json error_json = {
                {"error", {
                    {"message", std::string("Server error: ") + e.what()},
                    {"type", "server_error"}
                }}
            };
            return req->create_response(restinio::status_internal_server_error())
                .set_body(error_json.dump())
                .append_header("Content-Type", "application/json")
                .done();
        }
    }

    auto handle_list_models(auto req) {
        std::cout << "Handling /v1/models request" << std::endl;

        json response_json = {
            {"object", "list"},
            {"data", json::array()}
        };

        json model_obj = {
            {"id", "glm-4.7-fp8"},
            {"object", "model"},
            {"created", 1713950209},
            {"owned_by", "zai-org"},
            {"permission", json::array()},
            {"root", "glm-4.7-fp8"},
            {"parent", nullptr}
        };

        response_json["data"].push_back(model_obj);

        return req->create_response(restinio::status_ok())
            .set_body(response_json.dump())
            .append_header("Content-Type", "application/json")
            .done();
    }
