ServerConfig parse_env_config() {
    ServerConfig config;

    const char* host = std::getenv("HOST");
    if (host) config.host = host;

    const char* port = std::getenv("PORT");
    if (port) config.port = std::stoi(port);

    const char* model_dir = std::getenv("MODEL_DIR");
    if (model_dir) config.model_dir = model_dir;
    else config.model_dir = "/model/zai-org__GLM-4.7-FP8";

    const char* tp = std::getenv("TENSOR_PARALLEL_SIZE");
    if (tp) config.tensor_parallel_size = std::stoi(tp);

    const char* gpu_mem = std::getenv("GPU_MEMORY_FRACTION");
    if (gpu_mem) config.gpu_memory_fraction = std::stof(gpu_mem);

    const char* max_len = std::getenv("MAX_MODEL_LEN");
    if (max_len) config.max_model_len = std::stoi(max_len);

    const char* max_seqs = std::getenv("MAX_NUM_SEQS");
    if (max_seqs) config.max_num_seqs = std::stoi(max_seqs);

    const char* max_tokens = std::getenv("MAX_NUM_BATCHED_TOKENS");
    if (max_tokens) config.max_num_batched_tokens = std::stoi(max_tokens);

    const char* log_level = std::getenv("LOG_LEVEL");
    if (log_level) config.log_level = log_level;

    return config;
}

} // namespace tk_server

int main(int argc, char* argv[]) {
    signal(SIGINT, tk_server::signal_handler);
    signal(SIGTERM, tk_server::signal_handler);

    std::cout << "=== ThunderKittens GLM-4.7-FP8 Server ===" << std::endl;
    std::cout << "Starting up..." << std::endl;

    auto config = tk_server::parse_env_config();

    std::cout << "Configuration:" << std::endl;
    std::cout << "  Host: " << config.host << std::endl;
    std::cout << "  Port: " << config.port << std::endl;
    std::cout << "  Model Dir: " << config.model_dir << std::endl;
    std::cout << "  TP Size: " << config.tensor_parallel_size << std::endl;
    std::cout << "  GPU Memory Fraction: " << config.gpu_memory_fraction << std::endl;
    std::cout << "  Max Model Length: " << config.max_model_len << std::endl;
    std::cout << "  Max Sequences: " << config.max_num_seqs << std::endl;
    std::cout << "  Max Batched Tokens: " << config.max_num_batched_tokens << std::endl;

    auto server = std::make_unique<tk_server::TKServer>(config);

    if (!server->initialize()) {
        std::cerr << "Failed to initialize server" << std::endl;
        return 1;
    }

    std::cout << "Server initialized, starting HTTP listener..." << std::endl;
    std::cout << "Listening on " << config.host << ":" << config.port << std::endl;

    server->start();

    server->shutdown();

    std::cout << "Server exited" << std::endl;
    return 0;
}
